  "net_quantity": "200 g",
  "operator": "Denumirea și adresa operatorului"
})
});
const result = await response.json();
if (!response.ok) throw new Error(result.message || result.error_description || ('HTTP ' + response.status));
console.log(result);
```

### Python

```python
import json, urllib.request, urllib.parse, urllib.error

headers = {'Accept': 'application/json', 'Authorization': 'Bearer YOUR_ACCESS_TOKEN', 'Idempotency-Key': 'exemplu-v1PostManageTradeItemsIdLabels-001', 'Content-Type': 'application/json'}
payload = json.loads('{"version_key": "E1", "name": "Iaurt natural", "category": "lactate", "ingredients": "Lapte, culturi lactice.", "allergens": "Lapte.", "net_quantity": "200 g", "operator": "Denumirea și adresa operatorului"}')
data = json.dumps(payload).encode("utf-8")
request = urllib.request.Request('https://openaliment.ro/api/v1/manage/trade-items/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/labels', data=data, headers=headers, method='POST')
try:
    with urllib.request.urlopen(request, timeout=15) as response:
        print(json.load(response))
except urllib.error.HTTPError as error:
    print(error.code, error.read().decode("utf-8", errors="replace"))
    raise
```

## Răspunsuri

### 201 — Operația s-a încheiat; reluarea idempotentă poate întoarce aceeași resursă.

`application/json`

Exemplu sintetic:

```json
{
  "id": "ae9c3633477d9b04d94f1b3d3e1600fc",
  "state": "draft"
}
```

| Câmp | Tip | Obligatoriu | Semnificație și limite |
| --- | --- | --- | --- |
| `id` | string | Da | ID intern opac, 32 caractere hexazecimale mici; nu este GTIN. format regex: ^[a-f0-9]{32}$ |
| `state` | valoare fixă | Da | Starea resursei. Publicarea lotului și eliberarea sa sunt operații independente. valoare: "draft" |

Schema:

```json
{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^[a-f0-9]{32}$",
      "description": "ID intern opac, 32 caractere hexazecimale mici; nu este GTIN."
    },
    "state": {
      "const": "draft",
      "description": "Starea resursei. Publicarea lotului și eliberarea sa sunt operații independente."
    }
  },
  "required": [
    "id",
    "state"
  ],
  "additionalProperties": false,
  "description": "Structura LabelCreated. Exemplele sunt sintetice; permisiunile și stările reale se verifică la cerere."
}
```

### 400 — Cerere neinterpretabilă, JSON invalid sau credential în URL. Corectează formatul; trimite credentialele în antet/corp conform fluxului, fără retry automat.

`application/json`

Exemplu sintetic:

```json
{
  "error_code": "json",
  "message": "Cerere neinterpretabilă, JSON invalid sau credential în URL.",
  "request_id": "00000000000000000000000000000000"
}
```

Schema:

```json
{
  "type": "object",
  "required": [
    "error_code",
    "message",
    "request_id"
  ],
  "properties": {
    "error_code": {
      "type": "string",
      "description": "Cod stabil pentru tratarea programatică; textul message poate evolua."
    },
    "message": {
      "type": "string",
      "description": "Textul alertei sau al rezultatului, destinat persoanei care îl citește."
    },
    "request_id": {
      "type": "string",
      "description": "ID de corelare al cererii pentru suport; nu este credential sau ID de produs."
    }
  },
  "description": "Structura Error. Exemplele sunt sintetice; permisiunile și stările reale se verifică la cerere."
}
```

Antete: `X-Request-ID`: ID de corelare pentru suport; nu include cheia sau corpul privat în sesizări.

